## 13.  A Minimal “Hello, World!” TCP Server

```rust
use tokio::net::TcpListener;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

#[tokio::main]
async fn main() -> std::io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:12345").await?;

    println!("Listening on 127.0.0.1:12345");

    loop {
        let (socket, addr) = listener.accept().await?;
        println!("New connection from {}", addr);

        tokio::spawn(async move {
            if let Err(e) = handle_socket(socket).await {
                eprintln!("error handling socket: {:?}", e);
            }
        });
    }
}

async fn handle_socket(mut socket: tokio::net::TcpStream) -> std::io::Result<()> {
    let mut buf = [0u8; 1024];
    loop {
        let n = socket.read(&mut buf).await?;
        if n == 0 { return Ok(()); }          // client closed
        socket.write_all(&buf[..n]).await?;   // echo back
    }
}
```

Run it:

```bash
$ cargo run
$ nc 127.0.0.1 12345
hello
hello
```

